class Spelare:

    def __init__(self, namnet, poängen):
        """Skapar en spelare med ett namn (sträng) och en poäng (heltal)."""
        self.namn = namnet
        self.poäng = poängen

    def mer_poäng(self):
        """Ger spelaren en poäng till."""
        self.poäng += 1

    def till_rad(self):
        """Returnerar spelaren som en rad till filen, t.ex. "Emma;23"."""
        return self.namn + ";" + str(self.poäng)

    def __str__(self):
        """Returnerar en text om spelaren, t.ex. "Emma har 23 poäng"."""
        return self.namn + " har " + str(self.poäng) + " poäng"
